            f.values[0]+=mutate;w->unhappiness.players.at(player).happiness+=mutate;if(on_random)on_random(*w);const auto v=w->random.map.draw(static_cast<std::uint16_t>(bound));if(label.starts_with("culture:")){const auto actor=std::stoll(std::string(label.substr(8)));trace.push_back(actor);if(culture_hook)culture_hook(*w,actor);}return static_cast<std::int64_t>(v);
